def refs():
    return [{**s, "subject": "science", "locator": "花的構造、雄蕊與雌蕊、花藥與花粉、柱頭與花柱、子房與胚珠、授粉、花粉管、受精、種子與果實", "observedPattern": "公立學校公開生物科試題常以花的構造圖與授粉—花粉管—受精—果實／種子時間線，要求判斷構造功能和事件順序；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-db-iv-7-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供花的構造圖、授粉與受精順序、胚珠／種子／果實轉變的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "下列哪一組正確配對花的構造與功能？", {"A": "花藥—產生花粉；柱頭—接收花粉；子房內含胚珠", "B": "花瓣—產生卵細胞；花萼—製造花粉管", "C": "花柱—製造果實；花藥—保護根毛", "D": "胚珠—產生花粉；柱頭—儲存糖類供根吸收"}, "花藥是雄蕊的一部分，可產生花粉；柱頭位於雌蕊頂端，適合接收花粉；子房內有胚珠，胚珠內含卵細胞。", "先把雄蕊與雌蕊分組，再用產生、接收與保護胚珠三種功能核對。", ["辨認花藥屬於雄蕊。", "把花粉的產生配對花藥。", "把花粉的接收配對柱頭。", "確認子房內有胚珠，而非花粉。", "所以選 A。"], "easy"),
    make(2, "花粉由雄蕊花藥移到同一朵花或另一朵花的柱頭，這個事件稱為什麼？", {"A": "授粉", "B": "受精", "C": "萌發成種子", "D": "果實成熟"}, "花粉到達雌蕊柱頭是授粉；受精還要等花粉管把精細胞帶到胚珠，與卵細胞結合。", "名詞辨析題按事件發生的時間與位置區分授粉和受精。", ["先找題目描述的是花粉移動。", "確認花粉目的地是柱頭。", "把花粉到柱頭定義為授粉。", "排除精卵結合、種子形成與果實成熟等後續事件。", "所以選 A。"], "easy"),
    make(3, "開花植物由授粉到果實形成的合理順序為何？", {"A": "花粉到達柱頭→花粉管生長→精細胞與卵細胞結合→胚珠與子房後續發育", "B": "果實形成→授粉→花粉管生長→受精", "C": "受精→花粉到達柱頭→果實形成→花粉管生長", "D": "花粉管生長→果實形成→授粉→受精"}, "授粉先讓花粉到達柱頭，之後花粉萌發並長出花粉管，精細胞才可能到達胚珠與卵細胞結合；受精後胚珠和子房才進一步發育。", "流程題先固定最早的花粉位置，再依花粉管、受精和發育的先後排序。", ["找出授粉是花粉到達柱頭的起點。", "把花粉管生長放在柱頭接收到花粉之後。", "把精卵結合放在花粉管到達胚珠之後。", "將種子與果實的發育放在受精之後。", "所以選 A。"], "medium"),
    make(4, "若花粉管將精細胞送到胚珠附近，接下來最關鍵的事件是什麼？", {"A": "精細胞與胚珠內的卵細胞結合形成受精卵", "B": "花粉管變成根毛並吸收土壤水分", "C": "柱頭直接變成新的花粉", "D": "花瓣將受精卵排出花外"}, "花粉管的功能之一是引導精細胞到達胚珠，精細胞與卵細胞結合形成受精卵，這才是受精事件。", "將構造的運輸功能與真正的受精事件分開，避免把花粉管本身當成配子。", ["先確認花粉管是運送路徑。", "找出胚珠內的卵細胞是結合對象。", "把精細胞與卵細胞結合定義為受精。", "排除根毛、花粉與花瓣等錯誤轉變。", "所以選 A。"], "medium"),
    make(5, "受精完成後，胚珠與子房通常會分別發育成什麼？", {"A": "胚珠發育成種子，子房發育成果實", "B": "胚珠發育成果實，子房發育成根毛", "C": "胚珠發育成花粉，子房發育成莖", "D": "胚珠與子房都消失，不參與後續發育"}, "開花植物受精後，胚珠可發育成種子，子房壁及相關構造通常發育成果實的一部分；兩者的來源不能互換。", "轉變題先追蹤受精前的位置，再把胚珠與子房分別對應後續構造。", ["先定位胚珠在子房內。", "確認胚珠保護並包覆後續胚的發育，形成種子。", "確認子房相關組織發育成果實。", "排除花粉、根毛與互換來源的選項。", "所以選 A。"], "easy"),
    make(6, "昆蟲傳粉的花通常具有鮮豔花瓣或香味，這些特徵最可能的功能是？", {"A": "吸引傳粉者接近，增加花粉到達柱頭的機會", "B": "讓花朵直接把水吸進子房完成受精", "C": "使花粉不必經過柱頭就進入胚珠", "D": "把花瓣轉成種子以增加染色體數量"}, "鮮豔花瓣與香味可能吸引昆蟲或其他動物訪花，增加花粉轉移到柱頭的機會；它們不是直接把水送入子房的構造。", "適應題把外觀特徵連到傳粉者行為，再避免跳過授粉與受精步驟。", ["辨認題目描述的是傳粉媒介吸引。", "把顏色與香味連到訪花行為。", "確認功能是提高花粉轉移與授粉機會。", "排除直接吸水、繞過柱頭與染色體變化等說法。", "所以選 A。"], "easy"),
    make(7, "下列哪項最能區分自花授粉與異花授粉？", {"A": "花粉來源是同一朵或同一株的花，或來自另一株同種植物的花", "B": "花朵顏色是紅色或白色", "C": "受精後一定形成肉質果實或乾果", "D": "花粉是否含有精細胞"}, "自花授粉與異花授粉的區分重點在花粉來源；兩者的花粉都可含有精細胞，花色與果實型態不是定義。", "定義題先找事件中的來源關係，不被外觀或後續結果帶走。", ["找出自花與異花的共同事件是花粉到柱頭。", "比較花粉來自同一朵／同一株或另一株同種植物。", "確認花粉是否含精細胞不構成兩者差異。", "排除花色與果實型態等非定義特徵。", "所以選 A。"], "medium"),
    make(8, "若一朵花缺少花藥，最直接受影響的生殖步驟為何？", {"A": "無法正常產生該花的花粉，可能降低以自身花粉授粉的機會", "B": "無法形成任何胚珠，但花藥與胚珠是同一構造", "C": "會使根毛停止吸收水分", "D": "會使子房立刻變成葉片"}, "花藥負責產生花粉，缺少花藥會先影響花粉供應；胚珠位於雌蕊子房內，是不同構造。", "缺構造題先找該構造的直接產物，再只推論最接近的生殖後果。", ["辨認花藥是雄蕊構造。", "確認花藥的直接功能是產生花粉。", "推論花粉不足會影響授粉機會。", "排除胚珠、根毛與子房變葉等錯誤連結。", "所以選 A。"], "medium"),
    make(9, "研究花粉管是否受到雌蕊組織吸引時，哪種觀察最能支持『胚珠附近有引導作用』？", {"A": "在相同培養條件下，花粉管朝含胚珠材料的方向彎曲比例較高，且有適當對照", "B": "只觀察一條花粉管，未設對照就宣布所有花粉都會轉向", "C": "看到花朵漂亮，就推論花粉管一定被吸引", "D": "只測量花瓣長度，不觀察花粉管方向"}, "要支持引導作用，需在相同條件與對照下觀察花粉管方向或彎曲比例，才能把差異歸因於胚珠附近材料，而非其他條件。", "探究題檢查對照、重複、方向資料與因果範圍。", ["設定花粉管方向或彎曲比例為觀察指標。", "保持培養條件一致，只改變是否有胚珠材料。", "設置沒有胚珠材料的對照。", "重複觀察並限制結論，不從單一花粉管外推全部。", "所以選 A。"], "hard"),
    make(10, "要用模型完整說明花如何從授粉走到種子形成，哪組資訊最必要？", {"A": "雄蕊花藥與花粉、雌蕊柱頭／花柱／子房與胚珠、花粉管、精卵結合及受精後發育", "B": "只記錄花瓣顏色，不標示花粉與胚珠", "C": "只畫果實，不說明它與子房的關係", "D": "把授粉、受精、種子與果實形成視為同一個瞬間"}, "完整模型需交代花粉來源、雌蕊接收與引導、胚珠內卵細胞、精卵結合及胚珠／子房後續發育；只畫外觀或混合事件無法支持路徑。", "整合題採『來源—接收—引導—結合—發育』五段檢核。", ["先標示花藥產生花粉。", "畫出花粉到柱頭並經花柱向子房移動。", "標出胚珠內卵細胞與精卵結合。", "補上受精後胚珠成種子、子房成果實的發育。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
